import type { SVGProps } from "react";

export type ReflexLogoProps = Omit<SVGProps<SVGSVGElement>, "type"> & {
  /** "color" (brand colors, automatic dark mode) or "mono" (currentColor). */
  variant?: "color" | "mono";
  /** Accessible name. Pass "" when the logo is decorative. */
  title?: string;
};

const Icon = (props: SVGProps<SVGSVGElement>) => <svg xmlns="http://www.w3.org/2000/svg" fill="#6e56cf" viewBox="0 0 24 24" {...props}><path d="M17 15v9h5v-9zM2 0v24h5v-9h10v-5H7V5h10v5h5V0z" /></svg>;

const IconMono = (props: SVGProps<SVGSVGElement>) => <svg xmlns="http://www.w3.org/2000/svg" fill="currentColor" viewBox="0 0 24 24" {...props}><path d="M17 15v9h5v-9zM2 0v24h5v-9h10v-5H7V5h10v5h5V0z" /></svg>;

export function ReflexLogo({
  variant = "color",
  title = "Reflex",
  className,
  ...props
}: ReflexLogoProps) {
  const shared = {
    height: "1em",
    ...(title ? { role: "img", "aria-label": title } : { "aria-hidden": true }),
    ...props,
  } as SVGProps<SVGSVGElement>;

  if (variant === "mono") return <IconMono {...shared} className={className} />;

  return <Icon {...shared} className={className} />;
}

export default ReflexLogo;
